"""AST nodes produced by minisql.sqlparser (implementation plan section 3.4).

Every node carries `start`/`end` (offset of the first character and one past the last
character of the construct) and `pos` (the offset used for error reporting, spec 5.3).
Names are unescaped (quotes removed); their token offsets are kept in `*_pos` fields.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, List, Optional

# ---- expressions -------------------------------------------------------------------


@dataclass
class Literal:
    kind: str  # 'INTEGER' | 'REAL' | 'TEXT' | 'NULL'
    value: Any  # int | float | str | None
    start: int
    end: int
    pos: int  # the literal token


@dataclass
class ColumnRef:
    qualifier: Optional[str]
    name: str
    qualifier_pos: Optional[int]
    name_pos: int
    start: int
    end: int
    pos: int  # first token (== start)


@dataclass
class Unary:
    op: str  # '-' | '+'
    operand: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Binary:
    op: str  # arithmetic or comparison operator as written
    left: Any
    right: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Logical:
    op: str  # 'AND' | 'OR'
    left: Any
    right: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Not:
    operand: Any
    start: int
    end: int
    pos: int  # NOT token


@dataclass
class IsNull:
    operand: Any
    negated: bool
    start: int
    end: int
    pos: int  # IS token


@dataclass
class Like:
    operand: Any
    pattern: Any
    escape: Optional[Literal]  # TEXT literal or None
    negated: bool
    escape_pos: Optional[int]
    start: int
    end: int
    pos: int  # LIKE token (even when negated)


@dataclass
class InList:
    operand: Any
    items: List[Any]
    negated: bool
    start: int
    end: int
    pos: int  # IN token


@dataclass
class Call:
    name: str  # as written (unescaped if quoted)
    arg: Any  # expression, or None when star
    star: bool
    star_pos: Optional[int]
    start: int
    end: int  # one past ')'
    pos: int  # name token


@dataclass
class Paren:
    expr: Any
    start: int  # '('
    end: int  # one past ')'
    pos: int  # '('


# ---- clauses -----------------------------------------------------------------------


@dataclass
class StarItem:
    start: int
    end: int
    pos: int  # '*'


@dataclass
class QualifiedStarItem:
    qualifier: str
    qualifier_pos: int
    star_pos: int
    start: int
    end: int
    pos: int  # qualifier token


@dataclass
class ExprItem:
    expr: Any
    alias: Optional[str]
    alias_pos: Optional[int]
    start: int  # expression span only (alias excluded): output name = sql[start:end]
    end: int
    pos: int  # expression start


@dataclass
class TableRef:
    name: str
    name_pos: int
    alias: Optional[str]
    alias_pos: Optional[int]
    start: int
    end: int
    pos: int  # name token

    @property
    def range_name(self) -> str:
        return self.name if self.alias is None else self.alias

    @property
    def range_pos(self) -> int:
        return self.name_pos if self.alias is None else self.alias_pos


@dataclass
class Join:
    kind: str  # 'INNER' | 'LEFT'
    table: TableRef
    on: Any
    start: int  # first join keyword
    end: int
    pos: int  # first join keyword


@dataclass
class OrderItem:
    expr: Any
    desc: bool
    start: int
    end: int
    pos: int  # expression start


@dataclass
class Query:
    distinct: bool
    items: List[Any]
    from_table: Optional[TableRef]
    joins: List[Join]
    where: Any
    group_by: List[Any]
    having: Any
    order_by: List[OrderItem]
    limit: Optional[int]
    offset: Optional[int]
    start: int  # SELECT
    end: int  # one past the last consumed token (including ';')
    pos: int  # SELECT
"""Error hierarchy and position helper shared by every minisql phase."""
from __future__ import annotations

from typing import Optional, Tuple


def line_col(sql: str, offset: int) -> Tuple[int, int]:
    """1-based (line, column) for a code-point offset; lines split on '\\n' only."""
    line = sql.count("\n", 0, offset) + 1
    column = offset - (sql.rfind("\n", 0, offset) + 1) + 1
    return line, column


class MiniSQLError(Exception):
    kind = ""

    def __init__(self, message: str, line: Optional[int] = None, column: Optional[int] = None):
        self.message = message
        self.line = line
        self.column = column
        super().__init__(self._format())

    def _format(self) -> str:
        if self.kind == "IO":
            return "IOError: %s" % self.message
        return "%sError at line %s, column %s: %s" % (self.kind, self.line, self.column, self.message)

    def __str__(self) -> str:
        return self._format()

    @classmethod
    def at(cls, sql: str, offset: int, message: str) -> "MiniSQLError":
        line, column = line_col(sql, offset)
        return cls(message, line, column)


class LexError(MiniSQLError):
    kind = "Lex"


class ParseError(MiniSQLError):
    kind = "Parse"


class SemanticError(MiniSQLError):
    kind = "Semantic"


class QueryRuntimeError(MiniSQLError):
    kind = "Runtime"


class DataIOError(MiniSQLError):
    kind = "IO"
"""Storage layer: data-directory catalog, CSV loading and column type inference."""
from __future__ import annotations

import csv
import os
import re
from dataclasses import dataclass
from typing import List, Optional

from .errors import DataIOError

_INT_RE = re.compile(r"[+-]?[0-9]+")
_REAL_RE = re.compile(r"[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?")


@dataclass
class Table:
    stem: str
    file_name: str
    columns: List[str]
    types: List[str]
    rows: List[tuple]


class Catalog:
    def __init__(self, data_dir):
        self.path = os.fspath(data_dir)
        self.display = str(self.path)
        if not os.path.isdir(self.path):
            raise DataIOError("data directory not found: %s" % self.display)

    def _scan(self):
        """Fresh scan: list of (stem, path) for regular *.csv files."""
        try:
            with os.scandir(self.path) as it:
                return [
                    (e.name[:-4], e.path)
                    for e in it
                    if e.name.lower().endswith(".csv") and e.is_file()
                ]
        except (FileNotFoundError, NotADirectoryError):
            raise DataIOError("data directory not found: %s" % self.display) from None
        except OSError as exc:
            raise DataIOError(exc.strerror or str(exc)) from None

    def table_names(self) -> List[str]:
        return sorted((stem for stem, _ in self._scan()), key=lambda s: (s.lower(), s))

    def resolve(self, name: str) -> Optional[str]:
        key = name.lower()
        matches = [path for stem, path in self._scan() if stem.lower() == key]
        if len(matches) > 1:
            raise DataIOError("ambiguous table file '%s'" % name)
        return matches[0] if matches else None

    def load(self, name: str) -> Optional[Table]:
        path = self.resolve(name)
        return None if path is None else read_table(path)


def _infer(values):
    """(type, converted values) for one column of raw fields."""
    present = [v for v in values if v != ""]
    if not present:
        return "TEXT", [None] * len(values)
    if all(_INT_RE.fullmatch(v) for v in present):
        conv, kind = int, "INTEGER"
    elif all(_REAL_RE.fullmatch(v) for v in present):
        conv, kind = float, "REAL"
    else:
        conv, kind = str, "TEXT"
    return kind, [None if v == "" else conv(v) for v in values]


def read_table(path: str) -> Table:
    file_name = os.path.basename(path)
    stem = file_name[:-4]

    def fail(msg):
        return DataIOError("%s: %s" % (file_name, msg))

    header = None
    records = []
    reader = None
    try:
        with open(path, encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f, strict=True)
            for record in reader:
                if not record:
                    continue
                if header is None:
                    seen = set()
                    for col in record:
                        if col == "":
                            raise fail("empty column name")
                        if col.lower() in seen:
                            raise fail("duplicate column '%s'" % col)
                        seen.add(col.lower())
                    header = record
                elif len(record) != len(header):
                    raise fail(
                        "line %d: expected %d fields, got %d"
                        % (reader.line_num, len(header), len(record))
                    )
                else:
                    records.append(record)
    except csv.Error:
        raise fail("line %d: malformed CSV" % reader.line_num) from None
    except UnicodeDecodeError:
        raise fail("invalid UTF-8") from None
    except OSError as exc:
        raise fail(exc.strerror or str(exc)) from None
    if header is None:
        raise fail("empty file")

    types = []
    columns_data = []
    for i in range(len(header)):
        kind, values = _infer([r[i] for r in records])
        types.append(kind)
        columns_data.append(values)
    rows = list(zip(*columns_data)) if records else []
    return Table(stem, file_name, list(header), types, rows)

"""Recursive-descent parser for the contract grammar (EBNF and precedence table)."""
from __future__ import annotations

from .errors import ParseError
from .lexer import Token, tokenize
from .nodes import (
    Binary, Call, ColumnRef, ExprItem, InList, IsNull, Join, Like, Literal, Logical, Not,
    OrderItem, Paren, QualifiedStarItem, Query, StarItem, TableRef, Unary,
)

_CMP_OPS = ("=", "<>", "!=", "<", "<=", ">", ">=")
_NAME_KINDS = ("IDENT", "QIDENT")
_LITERAL_KINDS = {"INTEGER": "INTEGER", "REAL": "REAL", "STRING": "TEXT"}


def parse(sql: str) -> Query:
    return _Parser(sql, tokenize(sql)).query()


class _Parser:
    def __init__(self, sql, tokens):
        self.sql = sql
        self.tokens = tokens
        self.i = 0
        self.last_end = 0

    # ---- token helpers ----

    def peek(self, k=0) -> Token:
        return self.tokens[min(self.i + k, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.i]
        self.i += 1
        self.last_end = tok.end
        return tok

    def is_kw(self, word, k=0):
        tok = self.peek(k)
        return tok.kind == "KEYWORD" and tok.value == word

    def is_op(self, op, k=0):
        tok = self.peek(k)
        return tok.kind == "OP" and tok.value == op

    def accept_kw(self, word):
        return self.advance() if self.is_kw(word) else None

    def accept_op(self, op):
        return self.advance() if self.is_op(op) else None

    def error(self):
        tok = self.peek()
        if tok.kind == "EOF":
            return ParseError.at(self.sql, len(self.sql), "unexpected end of input")
        return ParseError.at(self.sql, tok.start, "unexpected token '%s'" % tok.text)

    def expect_kw(self, word):
        tok = self.accept_kw(word)
        if tok is None:
            raise self.error()
        return tok

    def expect_op(self, op):
        tok = self.accept_op(op)
        if tok is None:
            raise self.error()
        return tok

    def expect_name(self):
        if self.peek().kind not in _NAME_KINDS:
            raise self.error()
        return self.advance()

    def comma_list(self, parse_one):
        items = [parse_one()]
        while self.accept_op(","):
            items.append(parse_one())
        return items

    # ---- clauses ----

    def query(self):
        select = self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT") is not None
        items = self.comma_list(self.item)
        from_table, joins = None, []
        if self.accept_kw("FROM"):
            from_table = self.tableref()
            while True:
                join = self.join()
                if join is None:
                    break
                joins.append(join)
        where = self.expr() if self.accept_kw("WHERE") else None
        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by = self.comma_list(self.expr)
        having = self.expr() if self.accept_kw("HAVING") else None
        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by = self.comma_list(self.order)
        limit = self.integer() if self.accept_kw("LIMIT") else None
        offset = self.integer() if self.accept_kw("OFFSET") else None
        self.accept_op(";")
        if self.peek().kind != "EOF":
            raise self.error()
        return Query(distinct, items, from_table, joins, where, group_by, having, order_by,
                     limit, offset, select.start, self.last_end, select.start)

    def integer(self):
        if self.peek().kind != "INTEGER":
            raise self.error()
        return self.advance().value

    def item(self):
        tok = self.peek()
        if self.is_op("*"):
            self.advance()
            return StarItem(tok.start, tok.end, tok.start)
        if tok.kind in _NAME_KINDS and self.is_op(".", 1) and self.is_op("*", 2):
            self.advance()
            self.advance()
            star = self.advance()
            return QualifiedStarItem(tok.value, tok.start, star.start, tok.start, star.end, tok.start)
        expr = self.expr()
        alias, alias_pos = self.alias()
        return ExprItem(expr, alias, alias_pos, expr.start, expr.end, expr.start)

    def alias(self):
        if self.accept_kw("AS") or self.peek().kind in _NAME_KINDS:
            tok = self.expect_name()
            return tok.value, tok.start
        return None, None

    def tableref(self):
        name = self.expect_name()
        alias, alias_pos = self.alias()
        return TableRef(name.value, name.start, alias, alias_pos, name.start, self.last_end, name.start)

    def join(self):
        first = self.peek()
        if self.accept_kw("INNER"):
            self.expect_kw("JOIN")
            kind = "INNER"
        elif self.accept_kw("JOIN"):
            kind = "INNER"
        elif self.accept_kw("LEFT"):
            self.accept_kw("OUTER")
            self.expect_kw("JOIN")
            kind = "LEFT"
        else:
            return None
        table = self.tableref()
        self.expect_kw("ON")
        on = self.expr()
        return Join(kind, table, on, first.start, on.end, first.start)

    def order(self):
        expr = self.expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, desc, expr.start, self.last_end, expr.start)

    # ---- expressions ----

    def expr(self):
        return self.logical("OR", self.and_expr)

    def and_expr(self):
        return self.logical("AND", self.not_expr)

    def logical(self, word, operand):
        left = operand()
        while self.is_kw(word):
            op = self.advance()
            right = operand()
            left = Logical(word, left, right, left.start, right.end, op.start)
        return left

    def not_expr(self):
        tok = self.accept_kw("NOT")
        if tok is None:
            return self.cmp()
        operand = self.not_expr()
        return Not(operand, tok.start, operand.end, tok.start)

    def cmp(self):
        left = self.add()
        tok = self.peek()
        if tok.kind == "OP" and tok.value in _CMP_OPS:
            self.advance()
            right = self.add()
            return Binary(tok.value, left, right, left.start, right.end, tok.start)
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT") is not None
            self.expect_kw("NULL")
            return IsNull(left, negated, left.start, self.last_end, tok.start)
        negated = self.accept_kw("NOT") is not None
        kw = self.accept_kw("LIKE")
        if kw is not None:
            pattern = self.add()
            escape = None
            if self.accept_kw("ESCAPE"):
                if self.peek().kind != "STRING":
                    raise self.error()
                esc = self.advance()
                escape = Literal("TEXT", esc.value, esc.start, esc.end, esc.start)
            return Like(left, pattern, escape, negated, None if escape is None else escape.pos,
                        left.start, self.last_end, kw.start)
        kw = self.accept_kw("IN")
        if kw is not None:
            self.expect_op("(")
            items = self.comma_list(self.expr)
            self.expect_op(")")
            return InList(left, items, negated, left.start, self.last_end, kw.start)
        if negated:  # NOT after an operand must introduce NOT LIKE / NOT IN
            raise self.error()
        return left

    def add(self):
        return self.binary(("+", "-"), self.mul)

    def mul(self):
        return self.binary(("*", "/", "%"), self.unary)

    def binary(self, ops, operand):
        left = operand()
        while self.peek().kind == "OP" and self.peek().value in ops:
            op = self.advance()
            right = operand()
            left = Binary(op.value, left, right, left.start, right.end, op.start)
        return left

    def unary(self):
        tok = self.peek()
        if self.is_op("-") or self.is_op("+"):
            self.advance()
            operand = self.unary()
            return Unary(tok.value, operand, tok.start, operand.end, tok.start)
        return self.primary()

    def primary(self):
        tok = self.peek()
        if tok.kind in _LITERAL_KINDS:
            self.advance()
            return Literal(_LITERAL_KINDS[tok.kind], tok.value, tok.start, tok.end, tok.start)
        if self.is_kw("NULL"):
            self.advance()
            return Literal("NULL", None, tok.start, tok.end, tok.start)
        if self.is_op("("):
            self.advance()
            inner = self.expr()
            close = self.expect_op(")")
            return Paren(inner, tok.start, close.end, tok.start)
        if tok.kind not in _NAME_KINDS:
            raise self.error()
        self.advance()
        if self.is_op("("):
            self.advance()
            arg, star, star_pos = None, False, None
            if self.is_op("*"):
                star, star_pos = True, self.advance().start
            else:
                arg = self.expr()
            close = self.expect_op(")")
            return Call(tok.value, arg, star, star_pos, tok.start, close.end, tok.start)
        if self.accept_op("."):
            name = self.expect_name()
            return ColumnRef(tok.value, name.value, tok.start, name.start, tok.start, name.end, tok.start)
        return ColumnRef(None, tok.value, None, tok.start, tok.start, tok.end, tok.start)
