"""Semantic analysis: table loading, name resolution, static typing, aggregate and ORDER BY rules."""
from __future__ import annotations

from dataclasses import dataclass, fields, replace
from typing import Any

from . import nodes as n
from .errors import SemanticError
from .plan import (
    AggSpec, BAggRef, BArith, BCol, BCompare, BGroupRef, BIn, BIsNull, BLike, BLit, BLogical,
    BNot, BoundQuery, BUnary, OrderSpec,
)

_AGGREGATES = ("count", "sum", "avg", "min", "max")
_ARITH = ("+", "-", "*", "/", "%")
_NUMERIC = ("INTEGER", "REAL", "NULL")


@dataclass
class _AggCall:
    """Aggregate call before the group-level rewrite (never reaches the executor)."""
    func: str
    arg: Any  # row-level bound expression or None for '*'
    type: str
    pos: int


_BOUND = (BCol, BLit, BUnary, BArith, BCompare, BLogical, BNot, BIsNull, BLike, BIn, _AggCall)


def analyze(query: n.Query, sql: str, catalog) -> BoundQuery:
    return _Analyzer(sql, catalog).run(query)


def _children(b):
    for f in fields(b):
        v = getattr(b, f.name)
        if isinstance(v, _BOUND):
            yield v
        elif isinstance(v, list):
            yield from v


def _has_agg(b):
    return isinstance(b, _AggCall) or any(_has_agg(c) for c in _children(b))


def _key(b):
    """Structural identity key (Paren already dropped; '<>' == '!='; literals by type and value)."""
    if isinstance(b, BLit):
        return ("lit", b.type, b.value)
    if isinstance(b, BCol):
        return ("col", b.index)
    parts = [type(b).__name__]
    for f in fields(b):
        if f.name in ("type", "pos"):
            continue
        v = getattr(b, f.name)
        if isinstance(v, _BOUND):
            v = _key(v)
        elif isinstance(v, list):
            v = tuple(_key(x) for x in v)
        elif f.name == "op" and v == "<>":
            v = "!="
        parts.append(v)
    return tuple(parts)


def _comparable(a, b):
    return "NULL" in (a, b) or a == b == "TEXT" or (a in _NUMERIC and b in _NUMERIC and "TEXT" not in (a, b))


class _Analyzer:
    def __init__(self, sql, catalog):
        self.sql = sql
        self.catalog = catalog

    def error(self, offset, message):
        return SemanticError.at(self.sql, offset, message)

    def mismatch(self, offset, op, *types):
        return self.error(offset, "type mismatch: cannot apply '%s' to %s" % (op, " and ".join(types)))

    # ---- pass (a): resolve and type ----

    def run(self, q):
        tables, offsets, scope, seen, width = [], [], [], set(), 0
        refs = [] if q.from_table is None else [q.from_table] + [j.table for j in q.joins]
        for ref in refs:
            table = self.catalog.load(ref.name)
            if table is None:
                raise self.error(ref.name_pos, "unknown table '%s'" % ref.name)
            if ref.range_name.lower() in seen:
                raise self.error(ref.range_pos, "duplicate table name '%s'" % ref.range_name)
            seen.add(ref.range_name.lower())
            tables.append(table)
            offsets.append(width)
            scope.append((ref.range_name, table, width))
            width += len(table.columns)
        headers = [c for t in tables for c in t.columns]

        joins = [(j.kind, self.condition(j.on, scope[:i + 2], False)) for i, j in enumerate(q.joins)]

        select, columns, entries, aliases = [], [], [], []
        for item in q.items:
            if isinstance(item, n.ExprItem):
                b = self.bind(item.expr, scope, True)
                if item.alias is not None:
                    name = item.alias
                    aliases.append((item.alias.lower(), len(select)))
                elif isinstance(item.expr, n.ColumnRef):
                    name = headers[b.index]
                else:
                    name = self.sql[item.start:item.end]
                entries.append(("expr", len(select)))
                select.append(b)
                columns.append(name)
                continue
            if isinstance(item, n.StarItem):
                expand, star_pos = scope, item.pos
            else:
                expand = [s for s in scope if s[0].lower() == item.qualifier.lower()]
                if not expand:
                    raise self.error(item.qualifier_pos, "unknown table '%s'" % item.qualifier)
                star_pos = item.star_pos
            entries.append(("star", star_pos))
            for _, table, off in expand:
                for i, col in enumerate(table.columns):
                    select.append(BCol(off + i, col, table.types[i], star_pos))
                    columns.append(col)

        where = None if q.where is None else self.condition(q.where, scope, False)
        group_by = [self.bind(g, scope, False) for g in q.group_by]
        having = None if q.having is None else self.condition(q.having, scope, True)

        order = []  # (OrderItem, output index or None, bound expr or None)
        for item in q.order_by:
            e = item.expr
            if isinstance(e, n.Literal) and e.kind == "INTEGER":
                if not 1 <= e.value <= len(select):
                    raise self.error(e.pos, "ORDER BY position %s is out of range" % e.value)
                order.append((item, e.value - 1, None))
                continue
            if isinstance(e, n.ColumnRef) and e.qualifier is None:
                hits = [i for a, i in aliases if a == e.name.lower()]
                if len(hits) > 1:
                    raise self.error(e.pos, "ambiguous column '%s'" % e.name)
                if hits:
                    order.append((item, hits[0], None))
                    continue
            order.append((item, None, self.bind(e, scope, True)))

        # ---- pass (b): aggregate query, grouping, DISTINCT ----
        is_agg = (bool(group_by) or having is not None or any(_has_agg(b) for b in select)
                  or any(b is not None and _has_agg(b) for _, _, b in order))
        select_keys = [_key(b) for b in select]
        aggs = []
        if is_agg:
            gkeys, akeys = {}, {}
            for i, g in enumerate(group_by):
                gkeys.setdefault(_key(g), i)

            def group_level(b):
                k = _key(b)
                if k in gkeys:
                    return BGroupRef(gkeys[k], b.type, b.pos)
                if isinstance(b, _AggCall):
                    if k not in akeys:
                        akeys[k] = len(aggs)
                        aggs.append(AggSpec(b.func, b.arg, b.type, b.pos))
                    return BAggRef(akeys[k], b.type, b.pos)
                if isinstance(b, BLit):
                    return b
                if isinstance(b, BCol):
                    raise self.error(
                        b.pos, "column '%s' must appear in GROUP BY or be used in an aggregate" % b.name)
                changes = {}
                for f in fields(b):
                    v = getattr(b, f.name)
                    if isinstance(v, _BOUND):
                        changes[f.name] = group_level(v)
                    elif isinstance(v, list):
                        changes[f.name] = [group_level(x) for x in v]
                return replace(b, **changes)

            for kind, val in entries:
                if kind == "star":
                    raise self.error(val, "'*' not allowed in aggregate query")
                select[val] = group_level(select[val])
            if having is not None:
                having = group_level(having)

        specs = []
        for item, index, b in order:
            if b is not None and q.distinct:
                k = _key(b)
                if k not in select_keys:
                    raise self.error(
                        item.expr.start, "ORDER BY expression must appear in select list when DISTINCT is used")
                index = select_keys.index(k)
            if index is not None:
                specs.append(OrderSpec("output", index, None, item.desc))
            else:
                specs.append(OrderSpec("expr", None, group_level(b) if is_agg else b, item.desc))

        return BoundQuery(tables, offsets, joins, where, is_agg, group_by, aggs, having, select,
                          columns, [b.type for b in select], specs, q.distinct, q.limit, q.offset)

    def condition(self, e, scope, agg_ok):
        b = self.bind(e, scope, agg_ok)
        if b.type == "TEXT":
            raise self.error(e.start, "condition must be numeric, got TEXT")
        return b

    def column(self, e, scope):
        if e.qualifier is None:
            ref, cands = e.name, scope
        else:
            ref = "%s.%s" % (e.qualifier, e.name)
            cands = [s for s in scope if s[0].lower() == e.qualifier.lower()]
        matches = [(t, off, i) for _, t, off in cands
                   for i, c in enumerate(t.columns) if c.lower() == e.name.lower()]
        if not matches:
            raise self.error(e.pos, "unknown column '%s'" % ref)
        if len(matches) > 1:
            raise self.error(e.pos, "ambiguous column '%s'" % ref)
        t, off, i = matches[0]
        return BCol(off + i, ref, t.types[i], e.pos)

    def bind(self, e, scope, agg_ok):
        """Bottom-up: children are bound (and checked) before the node itself."""
        if isinstance(e, n.Paren):
            return self.bind(e.expr, scope, agg_ok)
        if isinstance(e, n.Literal):
            return BLit(e.value, e.kind, e.pos)
        if isinstance(e, n.ColumnRef):
            return self.column(e, scope)
        if isinstance(e, n.Call):
            return self.call(e, scope, agg_ok)
        if isinstance(e, (n.Unary, n.Not)):
            x = self.bind(e.operand, scope, agg_ok)
            op = "NOT" if isinstance(e, n.Not) else e.op
            if x.type not in _NUMERIC:
                raise self.mismatch(e.pos, op, x.type)
            if isinstance(e, n.Not):
                return BNot(x, "INTEGER", e.pos)
            return BUnary(e.op, x, x.type, e.pos)
        if isinstance(e, n.IsNull):
            return BIsNull(self.bind(e.operand, scope, agg_ok), e.negated, "INTEGER", e.pos)
        if isinstance(e, n.InList):
            x = self.bind(e.operand, scope, agg_ok)
            items = [self.bind(i, scope, agg_ok) for i in e.items]
            for i in items:
                if not _comparable(x.type, i.type):
                    raise self.mismatch(e.pos, "IN", x.type, i.type)
            return BIn(x, items, e.negated, "INTEGER", e.pos)
        left = self.bind(e.operand if isinstance(e, n.Like) else e.left, scope, agg_ok)
        right = self.bind(e.pattern if isinstance(e, n.Like) else e.right, scope, agg_ok)
        types = (left.type, right.type)
        if isinstance(e, n.Like):
            if not set(types) <= {"TEXT", "NULL"}:
                raise self.mismatch(e.pos, "LIKE", *types)
            escape = None
            if e.escape is not None:
                escape = e.escape.value
                if len(escape) != 1:
                    raise self.error(e.escape.pos, "ESCAPE must be a single character")
            return BLike(left, right, escape, e.negated, "INTEGER", e.pos)
        if isinstance(e, n.Logical) or e.op in _ARITH:
            if left.type not in _NUMERIC or right.type not in _NUMERIC:
                raise self.mismatch(e.pos, e.op, *types)
            if isinstance(e, n.Logical):
                return BLogical(e.op, left, right, "INTEGER", e.pos)
            t = "REAL" if "REAL" in types else "NULL" if types == ("NULL", "NULL") else "INTEGER"
            return BArith(e.op, left, right, t == "REAL", t, e.pos)
        if not _comparable(*types):
            raise self.mismatch(e.pos, e.op, *types)
        return BCompare(e.op, left, right, "INTEGER", e.pos)

    def call(self, e, scope, agg_ok):
        if e.name.lower() not in _AGGREGATES:
            raise self.error(e.pos, "unknown function '%s'" % e.name)
        func = e.name.lower().upper()
        if e.star and func != "COUNT":
            raise self.error(e.star_pos, "'*' argument only allowed for COUNT")
        if not agg_ok:
            raise self.error(e.pos, "aggregate function not allowed here")
        arg = None if e.star else self.bind(e.arg, scope, False)
        if func == "COUNT":
            t = "INTEGER"
        elif func in ("SUM", "AVG"):
            if arg.type == "TEXT":
                raise self.mismatch(e.pos, func, "TEXT")
            t = "REAL" if func == "AVG" else arg.type
        else:
            t = arg.type
        return _AggCall(func, arg, t, e.pos)

